package com.saludintegral.medico.controller;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid; import java.util.*; import com.saludintegral.medico.model.*; import com.saludintegral.medico.dto.*; import com.saludintegral.medico.services.MedicoService;
@RestController public class MedicoController {final MedicoService s;public MedicoController(MedicoService s){this.s=s;} @GetMapping("/api/medicos") public List<Medico> all(){return s.all();}@GetMapping("/api/medicos/{id}") public Medico get(@PathVariable Long id){return s.get(id);}@PostMapping("/api/medicos") public ResponseEntity<Medico> create(@Valid @RequestBody MedicoRequest x){return ResponseEntity.status(201).body(s.save(x));}@PutMapping("/api/medicos/{id}") public Medico update(@PathVariable Long id,@Valid @RequestBody MedicoRequest x){return s.update(id,x);}@DeleteMapping("/api/medicos/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/api/especialidades") public List<Especialidad> esp(){return s.especialidades();}@PostMapping("/api/especialidades") public ResponseEntity<Especialidad> crear(@Valid @RequestBody EspecialidadRequest x){return ResponseEntity.status(201).body(s.crearEspecialidad(x));} }
